  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (447::BIGINT, 'Se aprende mucho con ella, le gusta que los estudiantes hablen con ella y que comprendan la importancia del curso más allá de los libros. Tiene mucha experiencia en industria y es muy valioso'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '0e5946839d6e628cc94ca5a8ca18734509e3504908e2e9aa90f52942a8099080'::TEXT, ARRAY[1756]::BIGINT[]),
    (447::BIGINT, 'si quiere llevar el curso solo, llévelo con ella, explica solo si le preguntan y las evaluaciones son del wallpole entonces a veces son ejercicios muy volados'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-02-04T00:00:00+00:00'::TIMESTAMPTZ, '367a6bc12f176afbcf11f03700524915753a7292f2206dbc347b84f5eccb1d29'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Dema recomendada. Enseña sin complicar la vida, y se aprende mucho. Muy carismática y buena persona. Metro por si solo es aburrido pero ella es muy amena y hace lo mejor que puede'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '6a2a3fc06285ad7cbe4588551b6f6ed87244c24536d45de6111ede07e3e4fcfb'::TEXT, ARRAY[1756]::BIGINT[]),
    (447::BIGINT, 'Excelente profesora. Tiene mucho conocimiento de la materia, explica muy bien y se interesa mucho porque los estudiantes verdaderamente aprendan. Crea un ambiente muy bonito durante las clases.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b0ec73cb40341e5e997ea492c07b319ac6b103027ef12a0cff8c5c1f0effe8e3'::TEXT, ARRAY[1756]::BIGINT[]),
    (447::BIGINT, 'Bastante buena, comprometida con que el estudiante aprenda, califica el asistente y buena nota, en general si la recomiendo,(al final del curso pidió pizza para todos :)'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'a36026e7d3f866b7c8a6804dc8ff86fb8d7b9b94b6fb2527004bcf0f41abecff'::TEXT, ARRAY[1742]::BIGINT[]),
    (447::BIGINT, 'Hace el curso para que se aprenda bien los conceptos importantes. Se va el curso en lab y examenes, los 2 relativamente faciles pero los lab son largos y a veces poco claros. Las fechas se mueven constantemente. Pero todos pasan y en realidad se aprende mucho, ademas de la experiencia de la profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '6569bb375b812ca752f9f13c640f9ad836a4888dc150ff410cc4146bee04abfc'::TEXT, ARRAY[1756]::BIGINT[]),
    (447::BIGINT, 'Es muy agradable como persona, si le pregunta algo de verdad se esmera en que se resuelva la duda. A veces se hace bolas para explicar, pero en realidad con lo del libro se pasa con 100 el curso, el monthgomery. Los quices son un regalo, sorpresa pero regalo, examenes muy faciles.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '1bb2ce65a04d8ab12f6bf4f595bf39c5ad1351497b01af7e1c525c2ed32f2dd8'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (447::BIGINT, 'La Profe Paula es una excelente persona, es muy atenta a sus estudiantes y siempre busca formas para poder dar puntos extras a los estudiantes que se esfuerzen. Para lo examenes, practique muchos con Wallpole, no se quede solamente con los que vieron en clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2024-01-15T00:00:00+00:00'::TIMESTAMPTZ, '15f48a090e1150ad93ad22825a55f545ada0f5ed061d6d55b05da48ee69501e9'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (447::BIGINT, 'Como persona parece ser buena gente, pero es demasiado desordenada con las evaluaciones, cambia de opinión de manera imprevista y siempre hace lo que le da la gana con los exámenes, es un profe vaga aveces da clases virtuales, el curso se pasa pero no quita que la profesora sea un desorden'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2023-07-28T00:00:00+00:00'::TIMESTAMPTZ, '1f6172b9f200f804e0e03c8e430df6f46605c8978fd419aaedc1188dd7f345c9'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, 'No se prepara bien para las clases. Los últimos temas los explicó muy mal y nos enruedo a todos. Cuesta demasiado contactarla porque casi nunca responde el correo. No me parece una buena profesora'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '10fdd79b916f8b62e3c4c1eacbaeebdd8b08259fe3d9154063ec82e6354e8ca4'::TEXT, ARRAY[1742]::BIGINT[]),
    (447::BIGINT, 'La profe es muy buena gente y si se aprende con ella. No califica tan duro y los exámenes son al nivel de lo que se ve en clase. Si se confunde mucho en las clases, no está segura de las cosas entonces pasa preguntando o buscando pero en general es buena.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '67c2bc04ed43bbba2334274d1894b60bf095b4e30c4778c6bc6b07d3e864ef65'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (447::BIGINT, 'Los exámenes suelen ser muy confusos. Hay que ser autodidactas porque los ejemplos que hace en las clases son ejemplos hechos del libro. Se nota que no se prepara para dar las clases y no maneja muy bien los contenidos. Si tiene otra opción, descarte con Paula, no la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '13d487ea8a2381f606ce6315b131db5293432d47ac0e7bf393b87a2beb8c02bf'::TEXT, ARRAY[1742]::BIGINT[]),
    (447::BIGINT, 'La profe es muy buena gente, pero no sabe mucho de los temas. Casi siempre se enreda, en clases resuelve ejercicios hechos del libro porque no sabe hacer otros ejercicios. Los exámenes tienen una dificultad regular y baja puntos por cosas tontas (cantidad decimales, etc). No la recomiendo'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, '48f941328a4cfeb1a9ec2c5ab7c7590cf98a0324abc26539060fc5e07a0698ee'::TEXT, ARRAY[1742]::BIGINT[]),
    (447::BIGINT, 'Da las clases sincrónicas y se ayuda con videos de YT, en el semestre dio alrededor de 3 clases asincrónicas nada más. Deja varias tareas grupales entonces es bueno tener un buen grupo de trabajo, hay que tratar de eximirse porque son 3 exámenes. Hay muchos ejemplos similares en internet.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '827d75d79fba70bcb74159df530f685b23cefff3744a16f6555badf4874354af'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, 'Es la menos mala en comparación con el otro profesor que da el curso. La matería la presenta con videso de yt y presentaciones. No responde nos correos, entonces si tiene una duda busque en internet. Hay que ser muy autodidacta y autoresponderse las dudas solo. Las clases son aburridas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'abbb8251b636e6fea88dffef7cfea1d137ac6131732121ebe0de72b81dce827c'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, 'Participe hasta que se sepa su nombre (vale pts). Clases son 50/50 (a)sincrónicas por lo que importa hacerse un buen equipo para las tareas. Póngale a eximirse'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'b291e85d16539122a15e89a5a91153d20bc7def42f2a8d4dd9d54d822e64df0b'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, 'Las clases son semi-sincrónicas, deja tareas grupales casi todas las semanas bastante fáciles de hacer, la profe es un amor y brinda mucho apoyo, los exámenes se realizan en el TecDigital y a veces el tiempo no alcanza para realizarlos, la materia es bastante repetitiva, pero no es difícil'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '206cf092e001dd569ce087d0c05c155f11b902af563321bfd40966e039262816'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, 'El curso en general es fácil, la materia al final es repetitiva lo que facilita entenderla, el libro del curso ayuda mucho para profundizar el tema visto, ya que en clase a veces se ve lo más básico. La profe es buena gente y siempre disponible para consulta. Quices y tareas grupales.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '44471361c956d529e43de6737dce003d5e6b4a46a48b20030d0d95be64db3cc5'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, 'Paula es un amor. Las clases son dinámicas y pide mucha participación. Las tareas, quices y exámenes son super logrables. Como persona es un 10/10.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '8d9efa18db99f3833da312fd4cfa1ccea4172e4a2d8e0e157fc1023c42be2a17'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, '(VIRTUAL) En general, manda algunas tareas. Los exámenes son sencillos porque son en parejas, le gusta que la gente participe. La recomiendo para curso virtual'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '90fee0eb98113c9f9b8f0b8fd3ec6221bf5d9738b231fa63da57ae771bb0d56c'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, 'En si la profe es muy mala, solo se sabe guiar por las presentaciones o ejercicios que ella pone, los exámenes si son un poco volados, pide mucha participación en clase, MUCHA, así que prepárese para estar 3 horas sentado esperando que diga su nombre para que le conteste algo'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'b37f91e986f5f73a5aa0a5b666418f484fec6198f91255b015500417f7ebc094'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, 'Ayuda bastante y explica bien Los exámenes un poco confusos pero el curso es super pasable y ella es la mejor opción'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'eef1751304eef8035d57e44a5262e8b4c324eae0051b9e0af276b01e0febb94d'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Virtual: Quices teóricos. La materia es fácil Deja tareas que ayudan bastante para el examen Tareas y examenes se podían hacer con minitap, lo que ayuda un montón Fácil si estudia lo necesario. En grupo tareas y examen pero eso podria cambiar'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, '18a65089ed0e7e4f203b4ed6b3e8c0d3d2a7a9c344aad446b96b44fe588932ab'::TEXT, ARRAY[963]::BIGINT[]),
    (447::BIGINT, 'Excelente profe, lo llevé recién en verano y la clase es bastante amena y se aprende, que es lo importante. Deja bastantes tareas en grupo de dificultad media. Los exámenes son un poco largos y duros pero si se estudia las tareas y diapositivas le va bien porque los ejemplos son similares.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-07T00:00:00+00:00'::TIMESTAMPTZ, '8a1cf56863a4f1a037803096c9e5e0bc7ff4266301a464fe65938cfcae6f159d'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Es buena gente, pero no siempre demuestra un dominio completo sobre el tema (aveces las presentaciones tienen errores). Al principio deja muchas tareas pero se va relajando conforme pasan las clases. Califica justo y es muy importante la participación en clase.Es bueno estudiar con videos y el libro'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, '674a80bcf79240ca489405db3be38fe287d99b1fba78c44e1d935392f3ed139b'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Mala profesora, pierde muchísimo tiempo de la clase en cosas irrelevantes y luego ve la materia por encima, calcula o revisa mal las cosas y no da el brazo a torcer, por lo que pierdes puntos injustamente. En verano es lo peor, tiene que ser autodidacta completamente.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-01-07T00:00:00+00:00'::TIMESTAMPTZ, '6e94f3bef2ee106c11f240f5fc6c8bae25cd5e7e84e9cbd49dfd9aab89174f1d'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'A veces se aburre y ve la materia rápido, pero en general explica lo necesario y hace ejercicios parecidos a los del examen. La materia puede volverse pesada a veces.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2019-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'f3c8cba73000df6be36b6249b830f3ebcf39776538313901340bbbc412ebd534'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'En ocasiones se enreda y se contradice pero los ejemplos vistos en clase son bastante similares a los del examen. Hay que estudiar un poco por cuenta propia pero no es tan grave como con otros profesores. Los primeros dos exámenes son sencillos excepto el último que tiene una gran dificultad.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'c1d8d00819b0fb8350cca952cd7bb7f1987fa8fbe778d4b2af3c05ac4ed38832'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (447::BIGINT, 'Muy buena persona le interesa que los alumnos aprendan. Un amor de ser humano. Es dura pero uno sí aprende y no solo para el examen sino para la vida.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '19d1b20cdcf04ad9c1e17203282623a343bc123ffc612ab85e8fe731f2cea50f'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Es confusa, incluso a veces enseña un concepto de manera errónea y se da cuenta después cuando uno le lleva una duda del libro. Deja varias tareas al principio. Los exámenes no son muy complicados (menos el último, ese sí es duro). Es muy buena gente y trata de ayudar.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '7a858a00b6ea4f68d4e3c728f72432de6838a99fe5711145f13a9fedd9fd6d45'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'En clase no se entiende muy bien la materia, pero da las presentaciones, entonces, si estudia las mismas, se prepara bien, incluso puede complementarlo con el Walpole para entender mejor la materia. Es decir, se debe ser autodidacta.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '6effd9ed1d77c948e416c98fdf952f23a3c88a23dea7c14b0ebcdeb9476de22b'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'El curso es muy fácil, los temas son sencillos de aprender, pero la profesora a veces se enreda explicando y si uno le reclama algo de un examen es muy terca para dar la razón.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd8fbfc1328c060a93f67164be36fed1a1e03f70478016a74d4316842e6942b05'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (447::BIGINT, 'Uno tiene que estudiar por cuenta propia porque enreda mucho, algunas veces dice una cosa y después dice otra. Siempre atiende las consultas y como persona suele ser amable.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '52f27050b6504bbe420da4f7efbc3add02318d9fbf48823b712da95fcabd2038'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (447::BIGINT, 'Quiz o tarea todas las semanas, es buena gente, los examenes no son tan duros como dicen otras personas si uno de verdad estudió y los ejemplos de la clase son parecidos al examen, lo que si es que califica muy duro. Uno de verdad aprende, no solo para el curso sino también para la vida'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '5193c91cc9978d9ff08bb6a3f89c09d6bc19727ef43ce0fa8f39aa813850810d'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Todas las semanas hay quiz o tarea. Explica bien y si uno no entiende, tiene voluntad para volver a explicar. Da muchos ejemplos de la vida real. Los ejercicios que pone de práctica son muy básicos comparados a los del examen... hya que estudiar de verdad para pasar'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '474848c946b34db3e3d0e46dd5bbf8ac0da97ad4d5e7e2ac1ab87d0bfcae4409'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Si se quiere, no matricule con ella. Es un amor de persona hasta que llega el examen y no explicó en clase nada de lo que pone . Se hace bolas explicando los ejercicios y la verdad no sabe nada de lo que está hablando'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-26T00:00:00+00:00'::TIMESTAMPTZ, '75ba88eff5800e7a1e67b395aeafb71a0ac7c606c069d82fb62cf42559a19908'::TEXT, ARRAY[1742]::BIGINT[]),
    (447::BIGINT, 'Es una profe buena persona, muy dura con los quices y examenes. Se pasa pero tiene que ponerle estudiando, le gusta mucho que participemos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'c6a601bd6a92c839e3ce6f753a9e5d6a11b5ee3f91aa434a9580e538ffc2b4c8'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Es muy buena gente, hace varios ejercicios en clase y los exámenes son durillos pero nada de otro mundo. Deja tareas y hace pocos quices y duros.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-15T00:00:00+00:00'::TIMESTAMPTZ, '50bd3f70dad6fc2bcbdd4c378c53d29d1de78d9a2070cf9f8904d0caba543e3e'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Es una profe buena, hace muchos ejemplos en clase para que se comprenda la materia. Los exámenes son difíciles, se debe estudiar pero se pasa. Es estricta pero le gusta motivarnos a seguir adelante en la carrera. Usa muchos ejemplos de empresas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '283b902bb53f41b44f4efa7f0ece79aff8448cc8f2e5d66b8ed57125ff31611b'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'La profe es muy buena gente y explica claro, los examenes son muy parecidos a los ejercicios que se hacen en clase y las tareas. Califica duro y es importante llegar temprano a clase'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Brinda apoyo']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '27ab6a38538063b64f4960abadd02303b526e86cfd6271d11b201445ccbbb4ae'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'La clase es llevadera, da receso de 20min. Deja tareas grupales, hace quiz cada clase de la materia de la clase pasada, uno se la puede jugar con lo que ve en clase pero recomiendo buscar el Walpol para ejericios extra. Exámenes fáciles, pero largos. Exime si tienen nota de 60 antes del 3er examen'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'a849a6f776612156a9236bc4696bf0a65999b10692a10dea53ebb67da47d55e9'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'La verdad la profe se le confunden cosas básicas y tiende a confundir a los estudiantes , es buena gente pero complica las clases con mucha teoría'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2018-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'f798b6d10a97519160581dd48e092d96858d74b7c1c97b260013910f8fbfad90'::TEXT, ARRAY[1728]::BIGINT[]),
    (447::BIGINT, 'Es demasiado buena gente, se interesa que los estudiantes pasen el curso. Califica super fácil, los exámenes son exactamente en base a lo que se ve; pero mete mucha teoría en los exámenes. Tal vez te hagan falta bases para proba 2 pero lo pasas de fijo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'e22dacf95366be53f712fc439454d8636063efb2ef88c7bf22298e20189cc3d1'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (447::BIGINT, 'A veces tiende a confundirse pero si no entiendes la materia en clase, de fijo con una repasada en la casa se aprende. Es muy buena persona y le gusta ayudar a los estudiantes que no entienden. La recomiendo, aunque pueda que salga sin saber algunas cosas bien claras.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '097d43633786db28d72f83e40f3b08273181de0bca9371783350a96a6ddd561f'::TEXT, ARRAY[1728]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
